"""Write SANE configuration from PLATEN_* settings. Run by the container entrypoint.

    python -m app.container_setup [--sane-dir /etc/sane.d]
"""
from __future__ import annotations

import argparse
import re
from pathlib import Path

from .config import Settings, parse_entries


def airscan_conf(scanners: str, discovery: bool) -> str:
    lines = [
        "# Generated by platen at container start; edit PLATEN_SCANNERS instead.",
        "[options]",
        f"discovery = {'enable' if discovery else 'disable'}",
        "",
        "[devices]",
    ]
    for i, (name, url) in enumerate(parse_entries(scanners), start=1):
        protocol = "WSD" if "wsd" in url.lower() else "eSCL"
        label = re.sub(r'["\n]', "", name or f"Scanner {i}")
        lines.append(f'"{label}" = {url}, {protocol}')
    return "\n".join(lines) + "\n"


def dll_conf(backends: str) -> str:
    names = [b.strip() for b in backends.split(",") if b.strip()]
    return "# Generated by platen; set PLATEN_SANE_BACKENDS to change.\n" + "\n".join(names) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--sane-dir", default="/etc/sane.d", type=Path)
    args = parser.parse_args()
    settings = Settings()

    (args.sane_dir / "airscan.conf").write_text(
        airscan_conf(settings.scanners, settings.scanner_discovery)
    )
    (args.sane_dir / "dll.conf").write_text(dll_conf(settings.sane_backends))
    # Packages drop backend names into dll.d; keep only what was asked for.
    dll_d = args.sane_dir / "dll.d"
    if dll_d.is_dir():
        for entry in dll_d.iterdir():
            entry.unlink()


if __name__ == "__main__":
    main()
